    Bug 1953353 - Automatically set hierarchyDelimiter for IMAP accounts in xpcshell tests. r=mkmelin

    This is a required action for IMAP accounts and should be handled
    automatically.

    While we are here, let's use the the standard helper function to create
    subfolders in tests, which already properly wait for the folders being
    created.

    Differential Revision: https://phabricator.services.mozilla.com/D241150

diff --git a/mail/components/extensions/test/xpcshell/head.js b/mail/components/extensions/test/xpcshell/head.js
index a7b63995073..240ba57298d 100644
--- a/mail/components/extensions/test/xpcshell/head.js
+++ b/mail/components/extensions/test/xpcshell/head.js
@@ -65,6 +65,8 @@ function createAccount(type = "none") {
     account.incomingServer.port = IMAPServer.port;
     account.incomingServer.username = "user";
     account.incomingServer.password = "password";
+    const inbox = account.incomingServer.rootFolder.getChildNamed("INBOX");
+    inbox.QueryInterface(Ci.nsIMsgImapMailFolder).hierarchyDelimiter = "/";
   }

   if (type == "nntp") {
diff --git a/mail/components/extensions/test/xpcshell/test_ext_accounts.js b/mail/components/extensions/test/xpcshell/test_ext_accounts.js
index 595b7588a17..769e1846e28 100644
--- a/mail/components/extensions/test/xpcshell/test_ext_accounts.js
+++ b/mail/components/extensions/test/xpcshell/test_ext_accounts.js
@@ -299,18 +299,15 @@ add_task(async function test_accounts() {
   // According to the documentation of decodeURIComponent(), encodeURIComponent()
   // does not escape -.!~*'(), while decodeURIComponent() does unescape them.
   // Test our path-to-uri and uri-to-path functions can handle these special chars.
-  inbox1.createSubfolder("%foo.-~ %test% 'bar'(!)+", null);
-  inbox1.createSubfolder("Ϟ", null); // Test our code can handle unicode.
+  await createSubfolder(inbox1, "%foo.-~ %test% 'bar'(!)+");
+  await createSubfolder(inbox1, "Ϟ"); // Test our code can handle unicode.

   const inbox2 = account2.incomingServer.rootFolder.subFolders[0];
-  inbox2.QueryInterface(Ci.nsIMsgImapMailFolder).hierarchyDelimiter = "/";
   // According to the documentation of decodeURIComponent(), encodeURIComponent()
   // does not escape -.!~*'(), while decodeURIComponent() does unescape them.
   // Test our path-to-uri and uri-to-path functions can handle these special chars.
-  inbox2.createSubfolder("%foo.-~ %test% 'bar'(!)+", null);
-  await PromiseTestUtils.promiseFolderAdded("%foo.-~ %test% 'bar'(!)+");
-  inbox2.createSubfolder("Ϟ", null); // Test our code can handle unicode.
-  await PromiseTestUtils.promiseFolderAdded("Ϟ");
+  await createSubfolder(inbox2, "%foo.-~ %test% 'bar'(!)+");
+  await createSubfolder(inbox2, "Ϟ"); // Test our code can handle unicode.

   extension.sendMessage();

